s32 loadbit(JpegMpDecoderContext* pCtx)
{
    if(pCtx->bitlen == 0)
    {
        pCtx->bcode2 = pCtx->chitFF = pCtx->pSrc[(pCtx->srcOffset)++];
        if(pCtx->bcode2 == 0xFF)
        {
            (pCtx->srcOffset)++;
        }
        pCtx->bitlen = 8;
    }
    pCtx->bitlen--;
    return ((static_cast<s32>(pCtx->bcode2 >> pCtx->bitlen) & 1));
}

