                        JPEG_DECODER_USAT(w + ((u * s_CoefU2gMul + v * s_CoefV2gMul + s_CoefVu2gAdd) >> 15), 8);
                    d[e * 4 + 3] = JPEG_DECODER_USAT(w + ((v * s_CoefV2rMul + s_CoefV2rAdd) >> 14), 8);
