size_t JpegMpDecoder::GetWorkBufferSize()
{
    size_t size = 0;

    size += sizeof(detail::JpegMpDecoderWorkObj);

    return size;
}

void JpegMpDecoder::ClearTemporarySetting()
{
    memset(&m_TemporarySetting, 0, sizeof(m_TemporarySetting));
}

bool JpegMpDecoder::Initialize(void* workBuffer, size_t workBufferSize)
{
    u8* pBuf = static_cast<u8*>(workBuffer);
    size_t neededSize;

    m_Initialized = false;

    ClearTemporarySetting();

    NN_ALIGN_ASSERT_(workBuffer, 4);

    if(reinterpret_cast<u32>(workBuffer) & 3)
    {

        goto error;
    }

    neededSize = GetWorkBufferSize();
    if(!neededSize)
    {

        goto error;
    }
    if(workBufferSize < neededSize)
    {

        goto error;
    }
    memset(pBuf, 0, neededSize);

    m_pWork = reinterpret_cast<detail::JpegMpDecoderWorkObj*>(pBuf);
    pBuf += sizeof(*m_pWork);

    m_Initialized = true;
    return true;

error:
    return false;
}

size_t JpegMpDecoder::StartJpegDecoder(void* dst, size_t dstSize, const u8* src, size_t srcSize, u32 maxWidth,
                                       u32 maxHeight, PixelFormat dstPixelFormat, bool decodeThumbnail)
{
    size_t ret = 0;
    JpegMpDecoderContext* pCtx;

    if(!m_Initialized)
    {
        return 0;
    }

    pCtx = &m_pWork->ctx;

    ret = static_cast<size_t>(detail::InitializeJpegMpDecoderContext(pCtx, dst, dstSize, src, srcSize, maxWidth,
                                                                     maxHeight, dstPixelFormat, decodeThumbnail, false,
                                                                     &m_TemporarySetting));
    if(ret)
    {
        detail::Mel_JPEGDecodeFast(pCtx);

        if(pCtx->u.s.errorCode)
        {
            ret = 0;
        }
        else
        {

            ret = GetDstBufferSize(pCtx->outputBufferWidth, pCtx->outputBufferHeight, dstPixelFormat);
        }
    }

    ClearTemporarySetting();

    return ret;
}

size_t JpegMpDecoder::StartJpegDecoderShrink(void* dst, size_t dstSize, const u8* src, size_t srcSize, u32 maxWidth,
                                             u32 maxHeight, PixelFormat dstPixelFormat, bool decodeThumbnail,
                                             u32 shrinkLevel)
{
    size_t ret = 0;
    JpegMpDecoderContext* pCtx;

    if(!m_Initialized)
    {
        return 0;
    }

    pCtx = &m_pWork->ctx;

    if((shrinkLevel < MIN_DECODER_SHRINK_LEVEL) || (shrinkLevel > MAX_DECODER_SHRINK_LEVEL) ||
       (maxWidth & ((1 << shrinkLevel) - 1)) || (maxHeight & ((1 << shrinkLevel) - 1)))
    {
        detail::JpegMpDecoderSetError(pCtx, JPEG_DECODER_ERROR_INVALID_ARGUMENT);
        ret = 0;
    }
    else
    {

        ret = static_cast<size_t>(detail::InitializeJpegMpDecoderContext(
            pCtx, dst, dstSize, src, srcSize, maxWidth >> shrinkLevel, maxHeight >> shrinkLevel, dstPixelFormat,
            decodeThumbnail, false, &m_TemporarySetting));
        if(ret)
        {
            pCtx->shrinkLevel = shrinkLevel;
            pCtx->maxWidth = maxWidth;
            pCtx->maxHeight = maxHeight;

            if(pCtx->option & JPEG_DECODER_OPTION_MATCH_WIDTH_HEIGHT)
            {
                pCtx->matchWidth = maxWidth;
                pCtx->matchHeight = maxHeight;
            }

            detail::Mel_JPEGDecodeFast(pCtx);

            if(pCtx->u.s.errorCode)
            {
                ret = 0;
            }
            else
            {

                ret = GetDstBufferSize(pCtx->outputBufferWidth, pCtx->outputBufferHeight, dstPixelFormat);
            }
        }
    }

    ClearTemporarySetting();

    return ret;
}

bool JpegMpDecoder::ExtractExif(const u8* src, size_t srcSize, bool extractThumbnail)
{
    bool ret = false;
    JpegMpDecoderContext* pCtx;

    if(!m_Initialized)
    {
        return false;
    }

    pCtx = &m_pWork->ctx;

    ret = detail::InitializeJpegMpDecoderContext(pCtx, NULL, 0, src, srcSize, 0, 0, PIXEL_FORMAT_YUYV8,
                                                 extractThumbnail, true, &m_TemporarySetting);
    if(ret)
    {
        detail::Mel_JPEGDecodeFast(pCtx);

        if(pCtx->u.s.errorCode)
        {
            ret = false;
        }
        else
        {
        }
    }

    return ret;
}

